#!/usr/bin/env node
// One-off generator: parses MimeKit/Text/HtmlEntityDecoder.g.cs (the 12,445-line
// auto-generated trie tables) and emits ts/src/text/html-entity-data.ts.
//
// The .g.cs encodes an HTML5 named-character-reference trie as:
//   * MaxEntityLength                     -> maxEntityLength
//   * TransitionTable_<c> = Transition[]  -> transitionTables[c] = flat [from,to,...]
//     (keyed by the pushed char: '1'..'8', ';' (== "semicolon"), 'A'..'Z', 'a'..'z';
//      each array is sorted ascending by `from` so a binary search matches C#)
//   * NamedEntities = { [state] = "value" } -> namedEntities: state -> decoded string
//
// Usage: node gates/tools/gen-html-entities.mjs   (run from ts/)

import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const tsRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..');
const repoRoot = resolve(tsRoot, '..');
const srcPath = resolve(repoRoot, 'MimeKit', 'Text', 'HtmlEntityDecoder.g.cs');
const outPath = resolve(tsRoot, 'src', 'text', 'html-entity-data.ts');

const text = readFileSync(srcPath, 'utf8');

// --- MaxEntityLength ---
const maxMatch = text.match(/const int MaxEntityLength = (\d+);/);
if (!maxMatch) throw new Error('MaxEntityLength not found');
const maxEntityLength = parseInt(maxMatch[1], 10);

// --- Transition tables ---
// Each block: TransitionTable_<suffix> = new Transition[N] { new Transition (a, b), ... };
const tableKeyFor = (suffix) => (suffix === 'semicolon' ? ';' : suffix);
const transitionTables = {}; // char -> number[] (flat from,to pairs)
const tableRe = /TransitionTable_(\w+)\s*=\s*new Transition\[\d+\]\s*\{([\s\S]*?)\};/g;
let m;
let totalTransitions = 0;
while ((m = tableRe.exec(text)) !== null) {
  const key = tableKeyFor(m[1]);
  const body = m[2];
  const flat = [];
  const transRe = /new Transition\s*\(\s*(\d+)\s*,\s*(\d+)\s*\)/g;
  let t;
  let prevFrom = -1;
  while ((t = transRe.exec(body)) !== null) {
    const from = parseInt(t[1], 10);
    const to = parseInt(t[2], 10);
    if (from <= prevFrom) throw new Error(`table ${key}: not sorted ascending by from (${from} after ${prevFrom})`);
    prevFrom = from;
    flat.push(from, to);
    totalTransitions++;
  }
  transitionTables[key] = flat;
}

// --- NamedEntities ---
const dictMatch = text.match(/NamedEntities = new Dictionary<int, string>\s*\{([\s\S]*?)\n\s*\};/);
if (!dictMatch) throw new Error('NamedEntities dictionary not found');
const dictBody = dictMatch[1];
// [state] = "literal", where literal is a C# string using only \uXXXX / \" / \\ escapes,
// which are all valid JS string escapes -> copy the literal body verbatim.
const entryRe = /\[(\d+)\]\s*=\s*"((?:[^"\\]|\\.)*)"/g;
const entities = [];
let e;
while ((e = entryRe.exec(dictBody)) !== null) {
  entities.push([parseInt(e[1], 10), e[2]]);
}

// --- Emit ---
const lines = [];
lines.push('// AUTO-GENERATED by gates/tools/gen-html-entities.mjs from');
lines.push('// MimeKit/Text/HtmlEntityDecoder.g.cs. DO NOT EDIT.');
lines.push('');
lines.push(`export const maxEntityLength = ${maxEntityLength};`);
lines.push('');
lines.push('// Keyed by the pushed character; each value is a flat array of [from, to, from, to, ...]');
lines.push('// pairs sorted ascending by `from` (binary-searched by the decoder).');
lines.push('export const transitionTables: Record<string, readonly number[]> = {');
for (const [key, flat] of Object.entries(transitionTables)) {
  lines.push(`  ${JSON.stringify(key)}: [${flat.join(',')}],`);
}
lines.push('};');
lines.push('');
lines.push('// Map of trie state -> decoded entity value.');
lines.push('export const namedEntities: Record<number, string> = {');
for (const [state, literal] of entities) {
  lines.push(`  ${state}: "${literal}",`);
}
lines.push('};');
lines.push('');

writeFileSync(outPath, lines.join('\n'));
console.log(`wrote ${outPath}`);
console.log(`  maxEntityLength=${maxEntityLength}`);
console.log(`  transitionTables=${Object.keys(transitionTables).length} (keys), transitions=${totalTransitions}`);
console.log(`  namedEntities=${entities.length}`);
